eages": ["八幡信仰"], "sources": [{"name": "皇學館大学・県神社庁協力「新全国神社検索」", "url": "https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2396", "source_type": "shrine_association", "field_name": "shrine_information", "notes": "神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"}, {"name": "座標参照・地図情報", "url": "https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates", "source_type": "other", "field_name": "coordinates", "notes": "住所・自治体と座標を照合し、地図上の位置確認に使用。"}], "official_url": null, "slug": "iwate", "municipality": "盛岡市"}, {"name": "志和稲荷神社", "prefecture": "岩手県", "address": "岩手県紫波郡紫波町升沢字前平17番地", "latitude": 39.558979628, "longitude": 141.077875162, "history": "御裳裾を流れる滝名川の清流は心を洗い、千古の老杉が欝蒼と繁茂する霊場に鎮まります志和稲荷神社は、千年の歴史を伝える東北屈指の古社にして、生活生業万般に亘り広大無辺の御神徳あらたかな三柱の貴神を奉祭し、その連綿と続く歴史の中で人々の尊崇をあつめ、特に天喜五年に鎮守府将軍源頼義が社殿を再興したのを初めとして、平泉文化酣なわ頃は樋爪氏、中世には斯波氏、近世には南部藩主代々に亘り社領の寄進や社殿の造営を行い、天保五・六年には参詣街道を開削するなどして敬神の誠をつくしてこられましたと伝えられています。伝承には諸説あります。", "deities": ["宇迦之御魂大神", "猿田彦大神", "大宮能売大神"], "benefits": [], "lineages": ["稲荷信仰"], "sources": [{"name": "皇學館大学・県神社庁協力「新全国神社検索」", "url": "https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2425", "source_type": "shrine_association", "field_name": "shrine_information", "notes": "神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"}, {"name": "座標参照・地図情報", "url": "https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates", "source_type": "other", "field_name": "coordinates", "notes": "住所・自治体と座標を照合し、地図上の位置確認に使用。"}], "official_url": null, "slug": "iwate-shrine-1", "municipality": "紫波郡紫波町"}, {"name": "早池峰神社", "prefecture": "岩手県", "address": "岩手県遠野市附馬牛町上附馬牛第19地割81番地", "latitude": 39.4755737, "longitude": 141.5092865, "history": "当神社は遠野三山の主峰早池峰山の山霊を祀る。草創は大同元年（８０７）３月８日猟師四角藤蔵（後に始閣と定む）が早池峰山頂に於いて霊容を拝して発心、山道を拓いてその年の６月１８日山頂に７尺有余の宮を創建して早池峯大権現を祀ったのがこの社の始まりと伝えられていると伝えられています。伝承には諸説あります。", "deities": ["瀬織津姫命"], "benefits": [], "lineages": [], "sources": [{"name": "皇學館大学・県神社庁協力「新全国神社検索」", "url": "https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya