１０年１１月正面三層楼の洋風の県庁舎が完成開庁し、これに引き続き師範学校、警察本部、郡役所、銀行等々次々と建ち、雁島の湯殿山神社は、県庁のみならず山形中心部の鎮守と仰がれるようになったと伝えられています。伝承には諸説あります。", "deities": ["大山祇命", "大名持命", "少彦名命"], "benefits": [], "lineages": ["出雲系信仰"], "sources": [{"name": "皇學館大学・県神社庁協力「新全国神社検索」", "url": "https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2661", "source_type": "shrine_association", "field_name": "shrine_information", "notes": "神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"}, {"name": "座標参照・地図情報", "url": "https://www.openstreetmap.org/way/909125582", "source_type": "other", "field_name": "coordinates", "notes": "住所・自治体と座標を照合し、地図上の位置確認に使用。"}], "official_url": null, "slug": "yamagata-shrine-1", "municipality": "山形市"}, {"name": "伊佐須美神社", "prefecture": "福島県", "address": "福島県会津若松市神指町大字南四合字深川乙59", "latitude": 37.49276231, "longitude": 139.899995564, "history": "伊佐須美神社は福島県に鎮座する神社であり、由緒については諸説があると伝えられています。", "deities": ["伊邪那岐命", "伊邪那美命"], "benefits": [], "lineages": ["熊野信仰", "伊弉諾信仰"], "sources": [{"name": "皇學館大学・県神社庁協力「新全国神社検索」", "url": "https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=70034", "source_type": "shrine_association", "field_name": "shrine_information", "notes": "神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"}, {"name": "座標参照・地図情報", "url": "https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates", "source_type": "other", "field_name": "coordinates", "notes": "住所・自治体と座標を照合し、地図上の位置確認に使用。"}], "official_url": null, "slug": "fukushima", "municipality": "会津若松市"}, {"name": "相馬中村神社", "prefecture": "福島県", "address": "福島県相馬市沖ノ内字北町140・141", "latitude": 37.797312995, "longitude": 140.913017255, "history": "旧藩主家をはじめ相馬全領の総鎮守として庶民の御信仰を集めてまいりました当神社は、かっては「相馬妙見大明神」の旧称号で、一般には「相馬のオミョウケンサマ」と呼ばれ親しまれてまいりました。現在御祭神として天之御中主神をお祀りしておりますと伝えられています。伝承には諸説あります。", "deities": ["天御中主神"], "benefits": [], "lineages": [], "sources": [{"name": "皇學館大学・県神社庁協力「新全国神社検索」", "url": "https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2353", "source_type": "shrine_association", "field_name": "shrine_information", "notes": "神